package com.campusiq.user.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; private String college; private String branch; private Integer graduationYear; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void created(){createdAt=updatedAt=Instant.now();} @PreUpdate void updated(){updatedAt=Instant.now();} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v.toLowerCase();} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public String getCollege(){return college;} public String getBranch(){return branch;} public Integer getGraduationYear(){return graduationYear;} }
